CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS tenants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(64) NOT NULL UNIQUE, name varchar(255) NOT NULL, domain varchar(255) NOT NULL UNIQUE, status varchar(32) NOT NULL DEFAULT 'ACTIVE', tier varchar(32) NOT NULL DEFAULT 'STANDARD', settings_json jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS companies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, code varchar(64) NOT NULL, name varchar(255) NOT NULL, tax_id varchar(64) NOT NULL, currency varchar(10) NOT NULL DEFAULT 'USD', country varchar(100) NOT NULL, status varchar(32) NOT NULL DEFAULT 'ACTIVE', deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS branches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT, code varchar(64) NOT NULL, name varchar(255) NOT NULL, location_type varchar(32) NOT NULL, address text NOT NULL DEFAULT '', status varchar(32) NOT NULL DEFAULT 'ACTIVE', deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS business_units (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT, branch_id uuid REFERENCES branches(id) ON DELETE SET NULL, code varchar(64) NOT NULL, name varchar(255) NOT NULL, unit_type varchar(32) NOT NULL, status varchar(32) NOT NULL DEFAULT 'ACTIVE', deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES companies(id) ON DELETE RESTRICT, branch_id uuid REFERENCES branches(id) ON DELETE SET NULL, email varchar(255) NOT NULL, password_hash text NOT NULL, salt varchar(128) NOT NULL, full_name varchar(255) NOT NULL, phone varchar(64), department varchar(128) NOT NULL, designation varchar(128) NOT NULL, status varchar(32) NOT NULL DEFAULT 'ACTIVE', is_mfa_enabled boolean NOT NULL DEFAULT false, linked_employee_id varchar(64), linked_driver_id varchar(64), linked_operator_id varchar(64), last_login_at timestamptz, deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,email));
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, code varchar(64) NOT NULL, name varchar(255) NOT NULL, description text NOT NULL DEFAULT '', is_system_role boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code varchar(128) NOT NULL UNIQUE, module varchar(128) NOT NULL, action varchar(64) NOT NULL, description text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, assigned_at timestamptz NOT NULL DEFAULT now(), assigned_by uuid, UNIQUE(user_id,role_id));
CREATE TABLE IF NOT EXISTS role_permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_id uuid NOT NULL REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE, permission_code varchar(128) NOT NULL, UNIQUE(role_id,permission_id));
CREATE TABLE IF NOT EXISTS master_data (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, category varchar(64) NOT NULL, code varchar(64) NOT NULL, name varchar(255) NOT NULL, value_json jsonb NOT NULL DEFAULT '{}', status varchar(32) NOT NULL DEFAULT 'ACTIVE', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,category,code));
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, company_id uuid NOT NULL REFERENCES companies(id), module varchar(128) NOT NULL, entity_type varchar(128) NOT NULL, entity_id varchar(128) NOT NULL, file_name varchar(255) NOT NULL, file_size integer NOT NULL, mime_type varchar(128) NOT NULL, storage_key text NOT NULL, access_level varchar(32) NOT NULL, uploader_user_id uuid NOT NULL REFERENCES users(id), deleted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, recipient_user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title varchar(255) NOT NULL, body text NOT NULL, type varchar(32) NOT NULL, channel varchar(32) NOT NULL, is_read boolean NOT NULL DEFAULT false, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, actor_user_id uuid NOT NULL, actor_email varchar(255) NOT NULL, action varchar(128) NOT NULL, module varchar(128) NOT NULL, resource text NOT NULL, resource_id varchar(128), ip_address varchar(64) NOT NULL, correlation_id uuid NOT NULL, before_state_json jsonb, after_state_json jsonb, status varchar(32) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_definitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, code varchar(128) NOT NULL, name varchar(255) NOT NULL, entity_type varchar(128) NOT NULL, initial_state varchar(64) NOT NULL, states_json jsonb NOT NULL, transitions_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1, UNIQUE(tenant_id,code));
CREATE TABLE IF NOT EXISTS workflow_instances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, workflow_definition_id uuid NOT NULL REFERENCES workflow_definitions(id), entity_type varchar(128) NOT NULL, entity_id varchar(128) NOT NULL, current_state varchar(64) NOT NULL, initiated_by_user_id uuid NOT NULL REFERENCES users(id), status varchar(32) NOT NULL DEFAULT 'IN_PROGRESS', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS workflow_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE, instance_id uuid NOT NULL REFERENCES workflow_instances(id) ON DELETE CASCADE, from_state varchar(64) NOT NULL, to_state varchar(64) NOT NULL, action_name varchar(128) NOT NULL, actor_user_id uuid NOT NULL REFERENCES users(id), comments text, created_at timestamptz NOT NULL DEFAULT now());
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['companies','branches','business_units','users','roles','user_roles','master_data','documents','notifications','audit_logs','workflow_definitions','workflow_instances','workflow_actions'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I',t); EXECUTE format('CREATE POLICY tenant_isolation ON %I USING (tenant_id::text = current_setting(''app.current_tenant_id'', true))',t); END LOOP; END $$;
CREATE INDEX IF NOT EXISTS audit_logs_tenant_created_idx ON audit_logs(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS workflow_instances_entity_idx ON workflow_instances(tenant_id,entity_type,entity_id);
